+  provider: 'test-provider',
+  baseUrl: 'https://example.test',
+  contextWindow: 100000,
+  maxTokens: 4096,
+);
+
+final _at = DateTime.utc(2026);
+
+AssistantMessage _assistant(String text) => AssistantMessage(
+  content: [TextContent(text: text)],
+  api: 'test-api',
+  provider: 'test-provider',
+  m…

