const localTrimMarkerPrefix = '[context trimmed locally:';

final RegExp _markerTextPattern = RegExp(r'^\[\d+(?:-\d+)?:(?:hidden|ckpt)·');

/// Whether [text] opens like a projected hidden/checkpoint marker line —
