          if (resultId == null) {
            sawText = true;
            continue;
          }
          if (answered.contains(resultId)) {
            violations.add(
              ToolPairingViolation(
                ToolPairingViolationKind.duplicateResult,
                resultId,
                'a second tool_result answers the same id',
              ),
            );
          } else if (pending.contains(resultId)) {
            answered.add(resultId);
            if (sawText) {
