    'back from:\n\n<summary>\n';

/// Suffix closing [branchSummaryPrefix]. Ported from pi's
/// `BRANCH_SUMMARY_SUFFIX`.
const branchSummarySuffix = '\n</summary>';

/// The model binding a session's active branch was recorded with: the
