    out.write(text.substring(start, match.start));
    var end = close + 1;
    // A note occupying a whole line takes its line break with it, so the
    // strip does not leave a blank line behind.
    if (end < text.length &&
        text[end] == '\n' &&
        (match.start == 0 || text[match.start - 1] == '\n')) {
      end++;
    }
